// ClaimBuilder provides a fluent API for constructing Claim resources.
type ClaimBuilder struct {
	claim *Claim
}

// NewClaimBuilder creates a new ClaimBuilder.
func NewClaimBuilder() *ClaimBuilder {
	return &ClaimBuilder{
		// Nothing to set: the type marker carries the resource type, so the zero
		// value is already correct both in memory and on the wire.
		claim: &Claim{},
	}
}

// Build returns the constructed Claim resource.
func (b *ClaimBuilder) Build() *Claim {
	return b.claim
}

